'use strict';
// Same logical SQLite snapshot format as the existing pre-review fixtures.
// Restores actual historical rows before any current Store constructor runs.
const fs=require('node:fs'),path=require('node:path'),assert=require('node:assert/strict'),{createHash}=require('node:crypto'),{DatabaseSync}=require('node:sqlite');
const sha=value=>createHash('sha256').update(value).digest('hex'),sqlName=value=>'"'+value.replaceAll('"','""')+'"';
const pins={
 'activity-gap-038':{file:'72defd802ab3ed1d1c625f9b910aff9bb409df5954e7ef129643da6ceac48a7a',logical:'488836c86188ab1dbbca420f36d43c98d089ae6fda4eb65534b9e6e20046175d',source:'ab73d1956a934192d3aebe128b26ff4733142430b6ae0ccf440fd2324bc897c9',revision:'98738f964ab25a2fc3f5f2c77490f09fc92deea1',backend:'3f32757ba4318c3bd35dc58d7f9dcb7984e0ffdef609cd1af5abecb0e21f6658'},
 'clock-pending-039':{file:'de748b358f02b6d831ba9f4b9662eeee1d1bfa156487c23af5269d5a467c8ed1',logical:'714bc0fc72a87c962349b551d9e568f6338237c99f389103020d4d99d5556276',source:'70816b1fad62d654a0a8b2d0e9f0aea137956899dce842f3e3999f791041bebe',revision:'2c9dd77aa5c6f7fd8cf7ee2a7f82b07e357eb12b',backend:'cc81e014d1543aa99a1ca7f91e9202e0aa9e9bd8dbd96b8ea055ce05c3a56d62'}
};
function logicalSnapshot(db){const schema=db.prepare("SELECT type,name,tbl_name,sql FROM sqlite_master WHERE name NOT LIKE 'sqlite_%' AND sql IS NOT NULL ORDER BY type,name").all(),tables=schema.filter(row=>row.type==='table').map(table=>({name:table.name,columns:db.prepare('PRAGMA table_info('+sqlName(table.name)+')').all().map(column=>column.name),rows:db.prepare('SELECT rowid AS snapshot_rowid,* FROM '+sqlName(table.name)+' ORDER BY rowid').all()}));return {user_version:db.prepare('PRAGMA user_version').get().user_version,schema,tables,sequences:db.prepare('SELECT name,seq FROM sqlite_sequence ORDER BY name').all()};}
function load(name){const pin=pins[name];assert.ok(pin,'known historical fixture only');const bytes=fs.readFileSync(path.join(__dirname,name+'-snapshot.json'));assert.equal(sha(bytes),pin.file);const fixture=JSON.parse(bytes),p=fixture.provenance;assert.equal(fixture.format,'qq-fictional-sqlite-logical-snapshot-v1');assert.equal(p.source_revision,pin.revision);assert.equal(p.source_backend_hash,pin.backend);assert.equal(p.source_db_sha256,pin.source);assert.equal(p.logical_snapshot_sha256,pin.logical);assert.equal(sha(JSON.stringify(fixture.snapshot)),pin.logical);assert.equal(p.synthetic_only,true);assert.equal(p.http_attempts,0);assert.equal(JSON.stringify(fixture).includes('/home/'),false);assert.equal(JSON.stringify(fixture).includes('/tmp/'),false);return fixture;}
function restore(name,filename){
 assert.equal(fs.existsSync(filename),false,'snapshot restoration never overwrites a database');const fixture=load(name),{snapshot}=fixture,db=new DatabaseSync(filename);
 try{db.exec('BEGIN IMMEDIATE');for(const entry of snapshot.schema.filter(entry=>entry.type==='table'))db.exec(entry.sql);for(const table of snapshot.tables){const columns=['rowid',...table.columns],insert=db.prepare('INSERT INTO '+sqlName(table.name)+'('+columns.map(sqlName).join(',')+') VALUES('+columns.map(()=>'?').join(',')+')');for(const row of table.rows)insert.run(row.snapshot_rowid,...table.columns.map(column=>row[column]));}for(const entry of snapshot.schema.filter(entry=>entry.type!=='table'))db.exec(entry.sql);db.exec('DELETE FROM sqlite_sequence');for(const row of snapshot.sequences)db.prepare('INSERT INTO sqlite_sequence(name,seq) VALUES(?,?)').run(row.name,row.seq);assert.equal(snapshot.user_version,2);db.exec('PRAGMA user_version=2; COMMIT');assert.equal(sha(JSON.stringify(logicalSnapshot(db))),fixture.provenance.logical_snapshot_sha256,'exact old logical state before current Store open');
  const meta=db.prepare('SELECT error FROM memory_meta WHERE scope_key=?').get(JSON.stringify(Object.values(fixture.expected.scope)));assert.ok(meta);
  if(name==='activity-gap-038'){assert.equal(db.prepare('SELECT count(*) n FROM memory_gaps').get().n,1);assert.equal(db.prepare('SELECT count(*) n FROM memory_records').get().n,0);assert.equal(db.prepare("SELECT count(*) n FROM memory_journal WHERE status='pending'").get().n,0);assert.equal(fixture.expected.memoryStatus.pending,0);}
  else{assert.equal(JSON.parse(meta.error).code,'invalid_activity_event');assert.equal(db.prepare("SELECT count(*) n FROM memory_journal WHERE status='pending'").get().n,3);assert.equal(db.prepare('SELECT count(*) n FROM memory_records').get().n,0);assert.equal(fixture.expected.scriptedRequests,2);}
 }finally{db.close();}
 return {fixture,expected:fixture.expected,oldStateVerifiedBeforeCurrent:true,loadedDbSha256:sha(fs.readFileSync(filename))};
}
module.exports={load,restore};
